describe('Example Table Functionality', () => {
  it('should display the example table with correct data', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.get('#table1').should('be.visible');
    cy.get('#table1').contains('Last Name').should('be.visible');
    cy.get('#table1').contains('First Name').should('be.visible');
    cy.get('#table1').contains('Email').should('be.visible');
    cy.get('#table1').contains('Due').should('be.visible');
    cy.get('#table1').contains('Last Name', { text: 'Smith' }).should('be.visible');
    cy.get('#table1').contains('First Name', { text: 'John' }).should('be.visible');
    cy.get('#table1').contains('Email', { text: 'jsmith@gmail.com' }).should('be.visible');
    cy.get('#table1').contains('Due', { text: '2023-04-01' }).should('be.visible');
  });

  it('should not change the URL when clicking the table', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.get('#table1').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/tables');
  });
});
